for i,(id,title,ico,content) in enumerate(chapters,1):
 body+=f'<details id="{id}"><summary><span class="ico" aria-hidden="true">{ico}</span><span class="st"><small>MỤC {i:02d}</small><b>{title}</b></span><span class="arrow" aria-hidden="true">⌄</span></summary><div class="body">{content}</div></details>\n'
